struct Action {
    kind: String,
    name: String,
    expr: Option<Expr>,
    text: Option<String>,
    delay: i64,
}

struct State {
    id: String,
    kind: String,
    parent: usize,
    children: Vec<usize>,
    initial_name: Option<String>,
    deep: bool,
    default_name: Option<String>,
    entries: Vec<Vec<Action>>,
    exits: Vec<Vec<Action>>,
    transitions: Vec<usize>,
    depth: usize,
    initial: usize,
    default: usize,
    history: Option<Vec<usize>>,
    entered: usize,
    taken: usize,
    dwell: i64,
    entry_time: i64,
}

impl State {
    fn new(id: String, kind: String, parent: usize) -> Self {
        Self {
            id,
            kind,
            parent,
            children: Vec::new(),
            initial_name: None,
            deep: false,
            default_name: None,
            entries: Vec::new(),
            exits: Vec::new(),
            transitions: Vec::new(),
            depth: 0,
            initial: 0,
            default: 0,
            history: None,
            entered: 0,
            taken: 0,
            dwell: 0,
            entry_time: 0,
struct Transition {
    source: usize,
    trigger: String,
    descriptors: Vec<String>,
    delay: i64,
    guard: Option<Expr>,
    target: Option<usize>,
    mode: String,
    actions: Vec<Action>,
}

struct Definition {
    line: usize,
    text: String,
    node: Option<usize>,
}

#[derive(Clone)]
