}

impl Event {
    fn new(name: impl Into<String>, value: i64) -> Self {
        Self {
            name: name.into(),
            value,
struct Trigger {
    kind: &'static str,
    event: Option<Event>,
    transition: Option<usize>,
}

impl Trigger {
    fn kind(kind: &'static str) -> Self {
        Self {
            kind,
            event: None,
            transition: None,
        }
    }

    fn event(event: Event) -> Self {
        Self {
            kind: "event",
